use std::io::{self, BufWriter, Write};
use std::process::ExitCode;

use wgpu::util::DeviceExt;

const MAX_DIM: usize = 512;
const MAX_STEPS: usize = 1000;
const MAX_VALUE: u32 = 1_000_000;
const WORKGROUP: u32 = 8;

const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(8, 8)
fn step(@builtin(global_invocation_id) id: vec3<u32>) {
    if id.x >= params.width || id.y >= params.height {
        return;
    }
    let last_x = params.width - 1u;
    let last_y = params.height - 1u;
    let x = id.x;
    let y = id.y;
    let left = select(x - 1u, 0u, x == 0u);
    let right = select(x + 1u, last_x, x == last_x);
    let up = select(y - 1u, 0u, y == 0u);
    let down = select(y + 1u, last_y, y == last_y);

    let w = params.width;
    let centre = src[y * w + x];
    let sum = 4u * centre
        + src[y * w + left]
        + src[y * w + right]
        + src[up * w + x]
        + src[down * w + x];
    dst[y * w + x] = sum / 8u;
}
"#;

struct Grid {
    width: usize,
    height: usize,
    steps: usize,
    cells: Vec<u32>,
}

fn parse(text: &str) -> Result<Grid, String> {
    let mut tokens = text.split_ascii_whitespace();
    let mut next = |what: &str| -> Result<&str, String> {
        tokens.next().ok_or_else(|| format!("missing {what}"))
    };

    let width: usize = next("width")?.parse().map_err(|e| format!("bad width: {e}"))?;
    let height: usize = next("height")?.parse().map_err(|e| format!("bad height: {e}"))?;
    let steps: usize = next("steps")?.parse().map_err(|e| format!("bad steps: {e}"))?;
    if !(1..=MAX_DIM).contains(&width) || !(1..=MAX_DIM).contains(&height) {
        return Err(format!("grid size {width}x{height} out of range"));
    }
    if steps > MAX_STEPS {
        return Err(format!("steps {steps} out of range"));
    }

    let count = width * height;
    let mut cells = Vec::with_capacity(count);
    for i in 0..count {
        let value: u32 = next(&format!("cell {i}"))?
            .parse()
            .map_err(|e| format!("bad cell {i}: {e}"))?;
        if value > MAX_VALUE {
            return Err(format!("cell {i} value {value} out of range"));
        }
        cells.push(value);
    }

    Ok(Grid { width, height, steps, cells })
}

/// Runs `steps` stencil passes on the GPU, ping-ponging between two buffers,
/// and returns the final grid.
fn run_on_gpu(grid: &Grid) -> Result<Vec<u32>, String> {
    pollster::block_on(run_on_gpu_async(grid))
}

async fn run_on_gpu_async(grid: &Grid) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            ..Default::default()
        })
        .await
        .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default())
        .await
        .map_err(|e| format!("no GPU device: {e}"))?;

    let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("heat"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });

    let params = [grid.width as u32, grid.height as u32];
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::cast_slice(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });

    let size = (grid.cells.len() * std::mem::size_of::<u32>()) as u64;
    let storage = wgpu::BufferUsages::STORAGE
        | wgpu::BufferUsages::COPY_SRC
        | wgpu::BufferUsages::COPY_DST;
    let buf_a = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("a"),
        contents: bytemuck::cast_slice(&grid.cells),
        usage: storage,
    });
    let buf_b = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("b"),
        size,
        usage: storage,
        mapped_at_creation: false,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("heat layout"),
        entries: &[
            bind_entry(0, wgpu::BufferBindingType::Uniform),
            bind_entry(1, wgpu::BufferBindingType::Storage { read_only: true }),
            bind_entry(2, wgpu::BufferBindingType::Storage { read_only: false }),
        ],
    });
    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("heat"),
        bind_group_layouts: &[Some(&layout)],
        immediate_size: 0,
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat"),
        layout: Some(&pipeline_layout),
        module: &shader,
        entry_point: Some("step"),
        compilation_options: Default::default(),
        cache: None,
    });

    // Even steps read A and write B; odd steps read B and write A.
    let bind_ab = bind_group(&device, &layout, &params_buf, &buf_a, &buf_b);
    let bind_ba = bind_group(&device, &layout, &params_buf, &buf_b, &buf_a);

    let groups_x = (grid.width as u32).div_ceil(WORKGROUP);
    let groups_y = (grid.height as u32).div_ceil(WORKGROUP);

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("heat"),
    });
    for step in 0..grid.steps {
        let bind = if step % 2 == 0 { &bind_ab } else { &bind_ba };
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: Some("step"),
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, bind, &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }
    // After an even number of steps the result is in A, after an odd one in B.
    let result_buf = if grid.steps % 2 == 0 { &buf_a } else { &buf_b };
    encoder.copy_buffer_to_buffer(result_buf, 0, &readback, 0, size);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("map callback lost: {e}"))?
        .map_err(|e| format!("readback failed: {e}"))?;

    let data = slice.get_mapped_range();
    let cells: Vec<u32> = bytemuck::cast_slice(&data).to_vec();
    drop(data);
    readback.unmap();
    Ok(cells)
}

fn bind_entry(binding: u32, ty: wgpu::BufferBindingType) -> wgpu::BindGroupLayoutEntry {
    wgpu::BindGroupLayoutEntry {
        binding,
        visibility: wgpu::ShaderStages::COMPUTE,
        ty: wgpu::BindingType::Buffer {
            ty,
            has_dynamic_offset: false,
            min_binding_size: None,
        },
        count: None,
    }
}

fn bind_group(
    device: &wgpu::Device,
    layout: &wgpu::BindGroupLayout,
    params: &wgpu::Buffer,
    src: &wgpu::Buffer,
    dst: &wgpu::Buffer,
) -> wgpu::BindGroup {
    device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("heat bind"),
        layout,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: params.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: src.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 2,
                resource: dst.as_entire_binding(),
            },
        ],
    })
}

fn write_output(grid: &Grid, cells: &[u32]) -> io::Result<()> {
    let mut out = BufWriter::new(io::stdout().lock());
    let mut total: u64 = 0;
    for row in cells.chunks(grid.width) {
        let line: Vec<String> = row.iter().map(|v| v.to_string()).collect();
        writeln!(out, "{}", line.join(" "))?;
        total += row.iter().map(|&v| u64::from(v)).sum::<u64>();
    }
    writeln!(out, "SUM {total}")?;
    out.flush()
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: heat <input-file>");
        return ExitCode::FAILURE;
    };
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {path}: {e}");
            return ExitCode::FAILURE;
        }
    };
    let grid = match parse(&text) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("invalid input: {e}");
            return ExitCode::FAILURE;
        }
    };

    let cells = if grid.steps == 0 {
        grid.cells.clone()
    } else {
        match run_on_gpu(&grid) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("{e}");
                return ExitCode::FAILURE;
            }
        }
    };

    if let Err(e) = write_output(&grid, &cells) {
        eprintln!("write failed: {e}");
        return ExitCode::FAILURE;
    }
    ExitCode::SUCCESS
}

